#!/bin/sh
# Schema init job for PostgreSQL: loads the Guacamole schema if it is missing, checks the schema
# version of an existing database and secures the guacadmin account. Idempotent.
#
# Environment:
#   PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD  connection (libpq variables)
#   ADMIN_PASSWORD     password for guacadmin
#   ENFORCE_PASSWORD   "true" sets the password on every run
#   SCHEMA_FILE        SQL generated by initdb.sh
#   WAIT_TIMEOUT       seconds to wait for the database
set -eu

log() { echo "[schema-init] $*"; }
die() { echo "[schema-init] ERROR: $*" >&2; exit 1; }
query() { psql -X -v ON_ERROR_STOP=1 -tAc "$1"; }

[ -n "${ADMIN_PASSWORD:-}" ] || die "admin password is empty"

log "waiting for PostgreSQL at ${PGHOST}:${PGPORT} (timeout ${WAIT_TIMEOUT}s)"
elapsed=0
until query "SELECT 1" >/dev/null 2>&1; do
    [ "$elapsed" -lt "$WAIT_TIMEOUT" ] || { query "SELECT 1" || true; die "database not reachable after ${WAIT_TIMEOUT}s"; }
    sleep 5
    elapsed=$((elapsed + 5))
done

initialized=false
if [ "$(query "SELECT to_regclass('guacamole_user') IS NOT NULL")" = "f" ]; then
    log "schema not found, loading it"
    psql -X -q -v ON_ERROR_STOP=1 --single-transaction -f "$SCHEMA_FILE"
    initialized=true
    log "schema loaded"
else
    # Guacamole 1.6.0 added the AUDIT system permission (upgrade-pre-1.6.0.sql).
    has_audit="$(query "SELECT count(*) FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
                        WHERE t.typname = 'guacamole_system_permission_type' AND e.enumlabel = 'AUDIT'")"
    [ "$has_audit" = "1" ] || die "existing schema is older than 1.6.0. Upgrade it manually with
    upgrade-pre-1.6.0.sql (see /opt/guacamole/extensions/guacamole-auth-jdbc/postgresql/schema/upgrade/
    in the guacamole image) and run the upgrade again."
    log "schema exists and matches version 1.6"
fi

is_default="$(query "SELECT count(*) FROM guacamole_user u JOIN guacamole_entity e ON e.entity_id = u.entity_id
                     WHERE e.name = 'guacadmin' AND e.type = 'USER'
                       AND u.password_hash = sha256(convert_to('guacadmin' || upper(encode(u.password_salt, 'hex')), 'UTF8'))")"

if [ "$initialized" = "true" ] || [ "$ENFORCE_PASSWORD" = "true" ] || [ "$is_default" = "1" ]; then
    updated="$(psql -X -v ON_ERROR_STOP=1 -tA <<'SQL'
\getenv admin_password ADMIN_PASSWORD
WITH salt AS (
    SELECT sha256(convert_to(random()::text || clock_timestamp()::text, 'UTF8')) AS value
), updated AS (
    UPDATE guacamole_user u
    SET password_salt = salt.value,
        password_hash = sha256(convert_to(:'admin_password' || upper(encode(salt.value, 'hex')), 'UTF8')),
        password_date = CURRENT_TIMESTAMP
    FROM salt, guacamole_entity e
    WHERE e.entity_id = u.entity_id AND e.name = 'guacadmin' AND e.type = 'USER'
    RETURNING 1
)
SELECT count(*) FROM updated;
SQL
)"
    if [ "$updated" = "1" ]; then
        log "guacadmin password set from Secret"
    else
        log "user guacadmin does not exist, nothing to secure"
    fi
else
    log "guacadmin password was changed already, leaving it untouched"
fi

log "done"
